CREATE OR REPLACE FUNCTION public.keep_return_reminder_identity() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.id<>OLD.id OR NEW.rental_inquiry_id<>OLD.rental_inquiry_id OR NEW.stage<>OLD.stage OR NEW.recipient_email<>OLD.recipient_email OR NEW.reply_to<>OLD.reply_to OR NEW.customer_snapshot<>OLD.customer_snapshot THEN RAISE EXCEPTION 'Erinnerungsbeleg ist unveränderlich'; END IF; NEW.message_id:=OLD.message_id; NEW.actor_id:=OLD.actor_id; NEW.actor_name:=OLD.actor_name; NEW.created_at:=OLD.created_at; RETURN NEW; END $$;
CREATE TRIGGER keep_return_reminder_identity BEFORE UPDATE ON public.rental_return_reminders FOR EACH ROW EXECUTE FUNCTION public.keep_return_reminder_identity();